-- create "celebration_settings" table
CREATE TABLE "celebration_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "account_id" uuid NOT NULL, "timezone" character varying NOT NULL DEFAULT '', "birthday_balloons_visible" boolean NOT NULL DEFAULT true, "joined_at" timestamptz NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "celebrationsetting_account_id" to table: "celebration_settings"
CREATE UNIQUE INDEX "celebrationsetting_account_id" ON "celebration_settings" ("account_id");
-- create "celebration_views" table
CREATE TABLE "celebration_views" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "account_id" uuid NOT NULL, "kind" character varying NOT NULL, "surface" character varying NOT NULL, "local_date" character varying NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- create index "celebrationview_account_id_kind_surface_local_date" to table: "celebration_views"
CREATE UNIQUE INDEX "celebrationview_account_id_kind_surface_local_date" ON "celebration_views" ("account_id", "kind", "surface", "local_date");
